from django.db import transaction
from .models import Comment, Ticket

@transaction.atomic
def close_ticket(*,ticket:Ticket,actor,comment_text:str|None=None):
    if ticket.created_by_id != actor.id: raise PermissionError("Only the ticket owner may close this ticket.")
    ticket.status=Ticket.Status.CLOSED
    ticket.save(update_fields=["status","updated_at"])
    text=(comment_text or "").strip()
    if text: Comment.objects.create(ticket=ticket,author=actor,body=text)
    return ticket

