@login_required
def ticket_list(request):
    qs=Ticket.objects.filter(created_by=request.user).select_related("assignee").prefetch_related("labels")
    status=request.GET.get("status","").strip()
    q=request.GET.get("q","").strip()
    if status in {Ticket.Status.OPEN,Ticket.Status.CLOSED}: qs=qs.filter(status=status)
    if q: qs=qs.filter(title__icontains=q)
    page=Paginator(qs,20).get_page(request.GET.get("page"))
    return render(request,"tickets/list.html",{"page_obj":page,"status":status,"q":q})

def owned_ticket(user,ticket_id):
    return get_object_or_404(Ticket.objects.select_related("assignee").prefetch_related("labels","comments__author"),pk=ticket_id,created_by=user)

@login_required
def ticket_create(request):
    form=TicketForm(request.POST or None)
    if request.method=="POST" and form.is_valid():
        ticket=form.save(commit=False); ticket.created_by=request.user; ticket.save(); form.save_m2m()
        return redirect("ticket-detail",ticket_id=ticket.pk)
    return render(request,"tickets/form.html",{"form":form,"heading":"Create ticket"})

@login_required
def ticket_detail(request,ticket_id):
    ticket=owned_ticket(request.user,ticket_id)
    form=CommentForm(request.POST or None)
    if request.method=="POST" and form.is_valid():
        c=form.save(commit=False); c.ticket=ticket; c.author=request.user; c.save(); return redirect("ticket-detail",ticket_id=ticket.pk)
    return render(request,"tickets/detail.html",{"ticket":ticket,"comment_form":form})

@login_required
def ticket_edit(request,ticket_id):
    ticket=owned_ticket(request.user,ticket_id)
    form=TicketForm(request.POST or None,instance=ticket)
    if request.method=="POST" and form.is_valid(): form.save(); return redirect("ticket-detail",ticket_id=ticket.pk)
    return render(request,"tickets/form.html",{"form":form,"heading":"Edit ticket","ticket":ticket})

@login_required
def ticket_close(request,ticket_id):
    ticket=owned_ticket(request.user,ticket_id)
    if request.method=="POST":
        try: close_ticket(ticket=ticket,actor=request.user,comment_text=request.POST.get("comment"))
        except PermissionError: return JsonResponse({"detail":"Forbidden"},status=403)
    return redirect("ticket-detail",ticket_id=ticket.pk)

from rest_framework import serializers,viewsets,routers
from rest_framework.decorators import action
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from .models import Ticket
from .services import close_ticket

class TicketSerializer(serializers.ModelSerializer):
    class Meta:
        model=Ticket
        fields=["id","title","description","status","assignee","labels","created_at","updated_at"]
        read_only_fields=["id","status","created_at","updated_at"]
    def validate_title(self,value):
        value=value.strip()
        if len(value)<5: raise serializers.ValidationError("Title must contain at least 5 characters.")
        return value

class TicketViewSet(viewsets.ModelViewSet):
    serializer_class=TicketSerializer
    permission_classes=[IsAuthenticated]
    def get_queryset(self):
        return Ticket.objects.filter(created_by=self.request.user).select_related("assignee").prefetch_related("labels").order_by("-updated_at","-id")
    def perform_create(self,serializer): serializer.save(created_by=self.request.user)
    @action(detail=True,methods=["post"],url_path="close")
    def close(self,request,pk=None):
        ticket=self.get_object(); close_ticket(ticket=ticket,actor=request.user)
        return Response(self.get_serializer(ticket).data)

router=routers.DefaultRouter(); router.register("tickets",TicketViewSet,basename="api-ticket")

